python3 -c "
import json
d=json.load(open('studies/HIST_VNEXT/M06/BLOCKER_CERTIFICATE.json'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items():
            print(p+k, type(v).__name__, (str(v)[:90] if not isinstance(v,(dict,list)) else ''))
            if isinstance(v,dict) and p.count('.')<1: walk(v,p+k+'.')
    elif isinstance(o,list):
        print(p+'[]', 'len=%d'%len(o))
walk(d)
"

