import json
d=json.load(open('config/initial_state/hist_vnext_h4_v1/candidate_overlay.json',encoding='utf-8'))
def walk(o):
    if isinstance(o,dict):
        if o.get('data_role')=='candidate_linkage':
            yield o
        for v in o.values():
            yield from walk(v)
    elif isinstance(o,list):
        for v in o: yield from walk(v)
recs=list(walk(d))
print('candidate_linkage records:', len(recs))
from collections import Counter
print('admission_status:', Counter(r.get('admission_status') for r in recs))
print('purpose:', Counter(r.get('purpose') for r in recs))
print('evidence_kind:', Counter(r.get('evidence_kind') for r in recs))
print('has_value_ref:', Counter(('value_ref' in r) for r in recs))
"

